parameters.jsonBody:
={
  "model": "deepseek-ai/DeepSeek-V3",
  "messages": [
    {
      "role": "system",
      "content": "你是一个企业工单分析助手。你必须只返回 JSON，严禁输出任何额外文字。JSON格式：{\"category\":\"\",\"priority\":\"\",\"score\":\"\",\"queue\":\"\",\"department\":\"\",\"suggestion\":\"\"}。规则：1.score规则(返回数字):4(紧急):投诉/账号被盗/系统故障;3(高):发货延迟超3天/大额退款;2(中):一般退款/退换货;1(低):一般咨询/发货查询/发票账单。2.priority强制规则:只能输出文字，不能输出数字；分数4对应[紧急],3对应[高],2对应[中],1对应[1].3.queue规则:score=1->普通队列,score=2->售后队列,score=3->高级客服队列,score=4->主管处理队列。4.department规则:物流/发货->客服部,退货/换货->售后部,发票/账单->财务部,系统/登录->技术支持部。5.suggestion:若score>=3,标注\"需进入Pending Approval审批流\";若score<3,标注\"直接进入通知流程\"。"
    },
    {
      "role": "user",
      "content": "{{ $json.body.message }}"
    }
  ],
  "temperature": 0.1
}

assignments.value:
={{
  (() => {
    try {
      const content = JSON.parse($json.choices[0].message.content.replace(/```json/g, '').replace(/```/g, '').trim());
      // 获取 AI 的原始 priority
      const p = content.priority;
      // 归一化逻辑：如果 AI 返回的是 4，强制转为“紧急”；如果本身就是“紧急”，直接返回
      if (p == "4" || p == "紧急") return "紧急";
      if (p == "3" || p == "高") return "高";
      if (p == "2" || p == "中") return "中";
      return "低";
    } catch(e) {
      return "低";
    }
  })()
}}

={{ $json.priority === "紧急" ?  $now.plus({hours:24}).toFormat("yyyy-MM-dd HH:mm") : $json.priority === "高" ?  
$now.plus({hours:24}).toFormat("yyyy-MM-dd HH:mm") : $json.priority === "中" ? 
$now.plus({hours:48}).toFormat("yyyy-MM-dd HH:mm") : $now.plus({hours:72}).toFormat("yyyy-MM-dd HH:mm") }}
